from pathlib import Path
import json, html, collections, hashlib, zipfile
ROOT=Path(__file__).resolve().parent
D=ROOT/'dist'
rows=[('Обособленная велодорожка','#174BCC','Сплошная',''),('Велополоса на проезжей части','#6C91EF','Длинные штрихи','14 6'),('Велопешеходный путь','#4A9FD9','Сплошная, независимо от разделения с пешеходами',''),('Улица с велосипедным режимом','#7DB1D4','Штрихпунктир','14 4 2 4'),('Общая полоса с машинами или автобусами','#7DC8D4','Разреженные штрихи','5 13'),('Езда запрещена: bicycle=no','#D32F2F','Поперечные красные штрихи','1 7')]
style='''body{font:17px/1.6 system-ui,sans-serif;color:#28251f;background:#fffdf8;max-width:1080px;margin:auto;padding:24px}h1,h2,h3{line-height:1.25}h2{margin-top:36px}a{color:#704814}table{border-collapse:collapse;width:100%;margin:16px 0}td,th{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid #ddd5c7}code{overflow-wrap:anywhere;background:#eee8dd;padding:2px 4px}svg{width:150px;height:30px}.note{border-left:4px solid #b58c43;padding:12px;background:#f5efe2}summary{font-weight:600;cursor:pointer}details{margin:12px 0}li{margin:7px 0}.night code{color:#28251f}.night{background:#002a2a;color:#f4eee2;padding:18px}input{font:inherit;width:min(95%,600px);padding:10px}tr[hidden]{display:none}@media(max-width:600px){body{padding:14px;font-size:16px}table,tbody,tr,td,th{display:block}table{overflow:visible}tr{padding:12px 0;border-bottom:1px solid #ddd5c7}tr:has(th){display:none}td,th{border:0;padding:4px 0;overflow-wrap:anywhere}svg{width:150px}}'''
def doc(title,body):return '<!doctype html><html lang="ru"><meta charset="utf-8"><link rel="icon" href="data:, "><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+style+'</style><body>'+body+'</body></html>'
def swatch(c,dash):return f'<svg role="img" aria-label="Образец линии {c}" viewBox="0 0 150 30"><path d="M5 15H145" stroke="{c}" stroke-width="7" stroke-dasharray="{dash}" fill="none"/></svg>'
legend='<h1>Легенда CycloRoute Personal</h1><p>Версия 1.1 · целевая версия приложения: OsmAnd Android 5.4.11.</p><table><tr><th>Путь</th><th>Образец</th><th>Обозначение</th></tr>'
for name,col,note,dash in rows:legend+=f'<tr><td>{name}<br><code>{col}</code></td><td>{swatch(col,dash)}</td><td>{note}</td></tr>'
legend+='</table><div class="night"><h2>Те же велосипедные цвета ночью</h2>'+''.join(swatch(c,d) for _,c,_,d in rows)+'</div>'
legend+='''<p class="note">На стандартных картах боковые отметки и тип велоинфраструктуры могут быть закодированы раздельно. Цветная линия вдоль оси автомобильной дороги показывает тип прилегающей велоинфраструктуры, а нейтральные боковые штрихи — известную сторону. Цветная линия не означает, что нужно ехать по центру автомобильной дороги.</p>
<h2>Остальные дороги</h2><table><tr><th>Категория</th><th>День</th><th>Ночь</th></tr>'''
for name,day,night in [('Автомагистрали и trunk','#C5B6A4','#756755'),('Главные дороги','#D8C5A5','#81705A'),('Второстепенные дороги','#E5D8BD','#887B65'),('Местные связующие дороги','#EEE7D9','#807B70'),('Жилые и неклассифицированные улицы','#F4F1EB','#77736C'),('Служебные проезды','#E9E4DA','#716B62'),('Пешеходные улицы','#E6DDD4','#71675E'),('Хозяйственные дороги','#73634E','#73634E'),('Обычные тропы','#8C7458','#AE9C82')]:
 legend+=f'<tr><td>{name}</td><td>{swatch(day,"")}<code>{day}</code></td><td class="night">{swatch(night,"")}<code>{night}</code></td></tr>'
legend+='''</table><p>Мосты, тоннели, покрытия, качество дорог и остальные возможности CycloRoute сохранены. Покрытия, качество и обозначения велосипедных маршрутных сетей переведены из конфликтующих холодных цветов в тёплые. Вода, значки, здания, активная навигация, пользовательские GPX и избранное специально не перекрашены.</p>
<p>Из новых запретительных отметок добавлен только <code>bicycle=no</code>. Отсутствие красной отметки не подтверждает разрешение проезда.</p>
<h2>Полный каталог правил</h2><p>Ниже перечислены все правила точек, линий, площадей и подписей, включая вложенные условия из двух поставляемых файлов стиля. Это точный каталог правил, включая варианты и условия, а не обещание одновременно показать все объекты: видимость зависит от масштаба, данных и настроек. Общие селекторы с пустым значением могут обслуживать много разновидностей POI. Названия встроенных значков указаны в полях icon/shield; изображения самих значков здесь не подменены приближёнными картинками.</p>
<label>Найти объект или тег: <input id="search" type="search" placeholder="Например: waterway, parking, bicycle"></label><p id="count"></p>'''
catalog=json.loads((D/'rendering-catalog.json').read_text())
names={'line':'Линии','point':'Значки и точки','polygon':'Площади','text':'Подписи'}
for section,title in names.items():
 entries=[e for e in catalog if e['section']==section]
 legend+=f'<details><summary>{title} — {len(entries)} правил</summary><table><tr><th>Объект</th><th>Условия и оформление</th><th>Источник</th></tr>'
 for e in entries:
  tag=e.get('tag','');val=e.get('value','*') or '*'
  attrs={k:v for k,v in e.items() if k not in ['source','section','tag','value']}
  legend+='<tr class="entry"><td><code>'+html.escape(tag+'='+val if tag else e.get('element','условие'))+'</code></td><td>'+html.escape(json.dumps(attrs,ensure_ascii=False))+'</td><td>'+html.escape(e['source'])+'</td></tr>'
 legend+='</table></details>'
legend+='''<script>const s=document.getElementById('search'),r=Array.from(document.querySelectorAll('.entry')),c=document.getElementById('count');function filter(){const q=s.value.toLowerCase();let n=0;r.forEach(e=>{e.hidden=!e.textContent.toLowerCase().includes(q);if(!e.hidden)n++});c.textContent='Подходящих правил: '+n;if(q)document.querySelectorAll('details').forEach(e=>e.open=!!e.querySelector('.entry:not([hidden])'));}s.addEventListener('input',filter);filter();</script>
<p>Исходники: <a href="https://github.com/OsmAnd-Rendering/Cycling">CycloRoute</a> и <a href="https://github.com/osmandapp/OsmAnd-resources">OsmAnd resources</a>. Полные тексты лицензий находятся в архиве исходников.</p>'''
(D/'Легенда.html').write_text(doc('Легенда CycloRoute Personal',legend))

manual='''<h1>CycloRoute Personal — установка и использование</h1>
<p>Версия 1.1. Подготовлено для OsmAnd 5.4.11 на Android. Исходный CycloRoute сохранён как основа: изменено оформление дорог, а не настройки твоего профиля.</p>
<h2>1. Установить стиль</h2><ol>
<li>Сохрани резервную копию настроек OsmAnd через «Настройки → Экспорт в файл». Это особенно полезно перед импортом любых пользовательских пакетов.</li>
<li>Скопируй <code>CycloRoute-Personal.osf</code> на телефон. Открой файл через OsmAnd и импортируй оба стиля, карту легенды и отдельную группу избранного.</li>
<li>Включи свой обычный велосипедный профиль.</li>
<li>Открой «Настроить карту → Отрисовка карты → Стиль карты» и выбери <strong>CycloRoute Personal</strong>. Названия пунктов могут немного отличаться в переводе приложения.</li>
<li><code>CycloRoutePersonalBase</code> — технический родитель, его выбирать не нужно. Оба файла должны оставаться установленными.</li>
</ol>
<p>Пакет не импортирует велосипедный профиль и не сбрасывает твои виджеты, голос, настройки маршрута и записи треков. Для ручной установки файлов XML потребуются <em>оба</em> файла из папки rendering, а не только главный.</p>
<h2>2. Смотреть легенду</h2><ol>
<li>Открой «Мои места → Избранное → CycloRoute Personal → Легенда CycloRoute Personal» и покажи точку на карте.</li>
<li>Приблизь карту примерно до масштаба 17–18, затем прокручивай вниз: там расположены подписанные образцы.</li>
<li>Чтобы вернуться к себе, нажми кнопку местоположения. Для просмотра места, которое было на экране до легенды, лучше предварительно сохранить его маркером.</li>
</ol>
<p>Легенда работает без интернета. Это искусственный участок карты в море, не реальная инфраструктура. Он содержит только отображаемые объекты, без дорожного графа для расчёта маршрутов. <a href="Легенда.html">Отдельная полная справка</a> содержит выбранные цвета и поиск по всем явным правилам; её можно открыть браузером телефона без интернета.</p>
<h2>3. Строгие велосипедные маршруты</h2>
<p>Стиль карты и маршрутизация — разные настройки. В комплекте находится самостоятельный профиль <code>cycleways-strict.brf</code> для BRouter. Стиль можно использовать и без BRouter.</p>
<ol>
<li>Установи BRouter из F-Droid или Google Play. Запусти приложение и скачай данные своего региона через Download Manager. Эти данные обновляются отдельно от карт OsmAnd.</li>
<li>В файловом менеджере телефона открой <code>cycleways-strict.brf</code> через BRouter. В окне импорта сохрани имя файла и нажми Import. В BRouter 1.7.10 есть встроенный импорт BRF, поэтому вручную открывать Android/data обычно не требуется. Если Android не предлагает BRouter, попробуй «Открыть с помощью»; запасной вариант — скопировать файл в папку <code>brouter/profiles2</code> выбранного BRouter каталога данных с компьютера. Не заменяй <code>lookups.dat</code>.</li>
<li>В OsmAnd создай отдельный профиль на основе текущего велосипедного. Назови его точно <code>Brouter[cycleways-strict]</code>, включая скобки.</li>
<li>В настройках навигации этого профиля выбери «Тип навигации → Офлайн → Внешний → BRouter». Если пункта нет, сначала запусти BRouter и полностью перезапусти OsmAnd.</li>
<li>В этом же профиле выбери стиль CycloRoute Personal. Создай маршрут А–Б. Проверь начало, конец и пересечения на подробном масштабе.</li>
</ol>
<p>Если файловый доступ затруднён: открой <a href="https://brouter.de/brouter-web/">BRouter Web</a>, загрузи текст профиля через редактор профилей и экспортируй GPX. В OsmAnd используй исходный трек без приближения к дорогам и без пересчёта обычным велосипедным профилем. Такой GPX сам по себе не обеспечивает строгий пересчёт при отклонении.</p>
<h3>Что разрешено</h3><ul>
<li>Самостоятельные велодорожки.</li><li>Пути и пешеходные дорожки с явным велосипедным назначением <code>bicycle=designated</code>.</li>
<li>Улицы <code>bicycle_road=yes</code> / <code>cyclestreet=yes</code>. Машины на них могут быть разрешены.</li>
<li>Физически обособленная инфраструктура <code>cycleway=track</code> с учётом боковых тегов и направлений.</li>
</ul>
<h3>Что исключено</h3><p>Обычные дороги, велополосы с разметкой, общие полосы, автобусные полосы, обычные тротуары, лестницы, лифты, паромы, строящиеся и проектируемые дороги. Рекомендованный велосипедный маршрут и <code>bicycle=yes</code> сами по себе не открывают обычную дорогу. Явные ограничения доступа учитываются отдельно от цветов карты.</p>
<h3>Разрывы и другие случаи</h3><ul>
<li>Нет непрерывного разрешённого пути — маршрут не строится. Автоматического послабления нет.</li>
<li>Начало и конец привязываются к разрешённой сети в пределах 30 м. Это допуск позиционирования, не разрешённый автомобильный подъезд. Проверяй перенесённую точку.</li>
<li>Пешие подходы и переходы, не обозначенные как разрешённая велосипедная инфраструктура, не добавляются. Их нужно планировать отдельно.</li>
<li>При необходимости спешиться (<code>bicycle=dismount</code>) участок исключается из велосипедного маршрута.</li>
<li>Закрытые ворота и велобарьеры без явного велосипедного разрешения считаются непроходимыми: это консервативное решение.</li>
<li>По умолчанию профиль рассчитан на правостороннее движение. Для левосторонней страны измени <code>left_hand_traffic = true</code> и проверь направления.</li>
<li>Кольцевые автоматические маршруты не являются проверенным режимом этого профиля; используй обычные точки А–Б.</li>
<li>Профиль использует только теги, сохранённые в RD5. Динамическая обработка расписаний и всех conditional-тегов не реализована; данные и реальные знаки могут отличаться. Неизвестные значения велосипедной односторонности блокируются консервативно.</li>
</ul>
<p class="note">Если OsmAnd предлагает пересчёт другим движком, он уже не сохраняет ограничения этого профиля. При невозможности расчёта не переключайся автоматически на стандартный велосипедный профиль, ожидая того же результата.</p>
<h2>Видимость при отдалении</h2><p>В версии 1.1 велосипедные линии усилены: ширина 3–5 на масштабах 10–13, 6 на 14–15, 7–9 вблизи. Обводка шире линии на 2 единицы. Правила начинаются с масштаба 10, однако стиль может показать только объекты, присутствующие на этом уровне в OBF. На очень далёком масштабе стандартная карта может не содержать мелкие велопути на выбранном уровне данных.</p><h3>Велосеть на линейке 5 km без отдельных карт</h3><p>В профиле CycloRoute открой Configure map → Map rendering → Map magnifier и выбери 25%. Быстрый способ: удерживай кнопку + или − на карте. Затем кнопками масштаба выставь линейку 5 km. Пониженный magnifier позволяет показать более подробные данные при том же физическом охвате. На Galaxy S23 с OsmAnd 5.4.11 проверено: видно значительно больше велоинфраструктуры вокруг Гандии и Оливы. Настройка не привязана к региону и не требует отдельной обзорной карты. Подробнее становится вся карта, включая обычные дороги; при необходимости вернуть исходное значение — 100%. Сам файл стиля эту настройку не устанавливает.</p><h2>4. Обновление и возврат</h2><p>Для обновления импортируй новый пакет и выбирай замену одноимённых ресурсов. Если приложение предлагает создать копию точки легенды, выбери пропуск или замену: не создавай вторую группу. Для возврата выбери исходный CycloRoute; для обычной маршрутизации переключись на свой прежний велосипедный профиль. Добавленный стиль, карту легенды и группу избранного можно удалить отдельно.</p>
<h2>5. Что проверено</h2><p>Правила цвета проверены реальным Java-парсером OsmAnd; профиль маршрутизации — вычислителем выражений BRouter. Карта легенды собрана OsmAndMapCreator в формате OBF без раздела routing. Полный отчёт находится в <code>Проверки.txt</code>. Версия 1.0 импортирована и проверена на Galaxy S23 с OsmAnd 5.4.11: дневной и ночной режимы, легенда и bicycle=no. В версии 1.1 увеличена толщина велолиний; проверка этой версии на телефоне отмечается отдельно в отчёте.</p>
<p>Источники: <a href="https://osmand.net/docs/user/navigation/routing/brouter/">подключение BRouter</a>, <a href="https://osmand.net/docs/user/map/map-styles/">установка стилей</a>, <a href="https://github.com/OsmAnd-Rendering/Cycling">CycloRoute</a>.</p>'''
(D/'Инструкция.html').write_text(doc('CycloRoute Personal — инструкция',manual))
print('Written offline legend and instructions')
